#!/usr/bin/env python3
"""Console Checkers (Draughts) for two players.

Board squares are given as file+rank (e.g. ``c3``) or ``rank,file`` (e.g. ``3,4``).
Moves are entered as ``from-to`` (e.g. ``c3-d4`` or ``c3 to d4``).
Type ``q`` to quit, ``h`` for a list of legal moves.
"""

import re

SIZE = 8
RED, BLK = 'r', 'b'
FILES = 'abcdefgh'


def new_board():
    board = [['.' if (r + c) % 2 else ' ' for c in range(SIZE)] for r in range(SIZE)]
    for r in range(3):
        for c in range(SIZE):
            if (r + c) % 2:
                board[r][c] = BLK
    for r in range(5, SIZE):
        for c in range(SIZE):
            if (r + c) % 2:
                board[r][c] = RED
    return board


def inside(r, c):
    return 0 <= r < SIZE and 0 <= c < SIZE


def other(p):
    return BLK if p == RED else RED


def dirs_of(piece):
    if piece.isupper():
        return ((-1, -1), (-1, 1), (1, -1), (1, 1))
    return ((-1, -1), (-1, 1)) if piece == RED else ((1, -1), (1, 1))


def jumps_from(board, r, c):
    piece = board[r][c]
    foe = other(piece.lower())
    out = []
    for dr, dc in dirs_of(piece):
        mr, mc, lr, lc = r + dr, c + dc, r + 2 * dr, c + 2 * dc
        if inside(lr, lc) and board[mr][mc].lower() == foe and board[lr][lc] == '.':
            out.append((lr, lc))
    return out


def slides_from(board, r, c):
    piece = board[r][c]
    out = []
    for dr, dc in dirs_of(piece):
        lr, lc = r + dr, c + dc
        if inside(lr, lc) and board[lr][lc] == '.':
            out.append((lr, lc))
    return out


def sources(board, player, jumps):
    out = []
    for r in range(SIZE):
        for c in range(SIZE):
            if board[r][c].lower() == player:
                if jumps and jumps_from(board, r, c) or not jumps and slides_from(board, r, c):
                    out.append((r, c))
    return out
